6	/// The Insertion Modal's 3 tabs — Boundaries: "3 equal-width tabs (Texto/
7	/// Áudio/Foto)". Only [texto] is functional this story; [audio]/[foto]
8	/// render idle, non-interactive placeholders (Stories 3.2/3.3).
9	enum CaptureTab { texto, audio, foto }
10	
11	/// Capture's own state for the Insertion Modal — never the shared
12	/// `Resource<T>` (Boundaries). A sealed class, not `freezed` (no codegen
13	/// for this story beyond `entry_dto.g.dart`, Verification): every
14	/// variant always carries the common [activeTab]/[text] so switching tabs
15	/// or typing never needs to know which variant it's coming from.
16	sealed class TextEntryState {
17	  const TextEntryState({required this.activeTab, required this.text});
18	
19	  final CaptureTab activeTab;
20	  final String text;
21	}
22	
23	/// Ready to type/save — the state immediately after the modal opens
24	/// (Boundaries: "Opens on Texto, all 3 tabs idle/empty"), after a tab
25	/// switch, and after a keystroke.
26	class TextEntryIdle extends TextEntryState {
27	  const TextEntryIdle({required super.activeTab, required super.text});
28	}
29	
30	/// Salvar tapped, `POST /entries` in flight — the I/O matrix's "no
31	/// auto-retry, no double-submit": `InsertionModal` disables Salvar/the
32	/// text field for the duration of this state.
33	class TextEntrySaving extends TextEntryState {
34	  const TextEntrySaving({required super.activeTab, required super.text});
35	}
36	
37	/// The save attempt succeeded — `InsertionModal`'s listener reacts to
38	/// this by popping the sheet (I/O matrix: "success closes the modal").
39	/// Terminal: nothing meaningful follows it for this cubit instance, since
40	/// the modal (and the factory-scoped cubit backing it) is already
41	/// closing.
42	class TextEntrySaved extends TextEntryState {
43	  const TextEntrySaved({required super.activeTab, required super.text});
44	}
45	
46	/// The last save attempt failed (incl. offline, via the existing
47	/// `Failure.networkOffline`) — [message] is `Failure.message` verbatim
48	/// (I/O matrix: "Inline message from `Failure.message`"); Salvar is
49	/// re-enabled, the modal stays open, no auto-retry.
50	class TextEntryError extends TextEntryState {
51	  const TextEntryError({
52	    required super.activeTab,
53	    required super.text,
54	    required this.message,
55	  });
56	
57	  final String message;
58	}
59	
60	/// Drives `InsertionModal`. Calls [EntriesRepository.create] directly on
61	/// [save] — no use-case layer, matching this codebase's existing
62	/// convention (Design Notes: `AccountSettingsCubit`/`AuthCubit`). A fresh,
63	/// `get_it`-factory-scoped instance per "+" tap (Boundaries: "Modal open
64	/// resets") — starting state is always [TextEntryIdle] on
65	/// [CaptureTab.texto] with empty text, so no explicit reset method is
66	/// needed the way `AccountSettingsCubit.clearStaleError()` needs one for
67	/// its own long-lived singleton.
68	class TextEntryCubit extends Cubit<TextEntryState> {
69	  TextEntryCubit(this._repository)
70	    : super(const TextEntryIdle(activeTab: CaptureTab.texto, text: ''));
71	
72	  final EntriesRepository _repository;
73	
74	  /// Switches the active tab, preserving whatever Texto text was already
75	  /// typed. The cross-tab cancel-safety rule (FR-11) lives in
76	  /// `insertion_modal.dart`'s tab-switch dispatch
77	  /// (`_onTextEntryStateChange`), not here — Texto needs no `cancel()` of
78	  /// its own because no async op ever precedes Salvar on this tab, unlike
79	  /// Áudio's recording or Foto's pick/OCR.
80	  ///
81	  /// Review finding: ignored while [TextEntrySaving] — `InsertionModal`
82	  /// already disables the tab bar for that case, but this is the
83	  /// authoritative guard regardless of how `selectTab` is invoked. Without
84	  /// it, switching away mid-save would still let `save()`'s eventual
85	  /// `TextEntrySaved`/`TextEntryError` emission land on top of whatever
86	  /// tab/text the user has since moved to — popping the modal
87	  /// unexpectedly, or showing an error against an unrelated tab.
88	  void selectTab(CaptureTab tab) {
89	    if (tab == state.activeTab || state is TextEntrySaving) {
90	      return;
91	    }
92	    emit(TextEntryIdle(activeTab: tab, text: state.text));
93	  }
94	
95	  /// Mirrors the Texto field's own `TextEditingController` into this
96	  /// cubit's state, so [save] has the latest typed text to send. Ignored
97	  /// while a save is already in flight — the field is disabled in that
98	  /// state (`InsertionModal`), so this should never fire then regardless.
99	  void updateText(String text) {
100	    if (state is TextEntrySaving) {
101	      return;
102	    }
103	    emit(TextEntryIdle(activeTab: state.activeTab, text: text));
104	  }
105	
106	  /// I/O matrix's "Happy path save"/"Save fails" rows: fires `POST
107	  /// /entries` with `source: manual` (Boundaries — the only source this
108	  /// story ever sends) for whatever non-empty text is currently typed. A
109	  /// blank/whitespace-only text never calls [EntriesRepository.create] —
110	  /// `InsertionModal` already disables Salvar for that case, but this is
111	  /// the authoritative guard regardless of how `save()` is invoked.
112	  ///
113	  /// Review finding: also ignored while already [TextEntrySaved] — the
114	  /// modal's dismiss animation keeps this cubit alive (and Salvar
115	  /// re-enabled, since that state isn't [TextEntrySaving]) for its
116	  /// duration, so without this a fast double-tap on Salvar could fire a
117	  /// second, un-deduplicated `create` call before the sheet finishes
118	  /// closing.
119	  Future<void> save() async {
120	    final text = state.text.trim();
121	    if (text.isEmpty || state is TextEntrySaving || state is TextEntrySaved) {
122	      return;
123	    }
124	    final activeTab = state.activeTab;
125	    emit(TextEntrySaving(activeTab: activeTab, text: text));
126	    final result = await _repository.create(
127	      content: text,
128	      source: EntrySource.manual,
129	    );
130	    // Mirrors `AccountSettingsCubit.toggleBiometric`'s own guard: this
131	    // cubit's `dispose:`/`close()` can race the awaited call above (e.g.
132	    // the modal's barrier is dismissed mid-save) — `emit()` after `close()`
133	    // would otherwise throw.
134	    if (isClosed) {
135	      return;
136	    }
137	    result.match(
138	      (failure) => emit(
139	        TextEntryError(activeTab: activeTab, text: text, message: failure.message),
140	      ),
141	      (_) => emit(TextEntrySaved(activeTab: activeTab, text: text)),
142	    );
143	  }
144	}
