34	/// Scriptable fakes (not mocktail — same "plain fake" convention
35	/// `insertion_modal_test.dart`'s own `_FakeEntriesRepository` already
36	/// uses for widget-level tests) standing in for the two native-package
37	/// ports this story adds. Never exercises the real `record`/
38	/// `whisper_ggml` plugins (Never, AGENTS.md: no device/simulator exists).
39	class _FakeMicRecorder implements MicRecorder {
40	  bool permissionGranted = true;
41	  int startCalls = 0;
42	  int cancelCalls = 0;
43	  MicRecording? nextStopResult;
44	
45	  /// Lets a test drive `_Waveform`'s own `amplitudeStream.listen(...,
46	  /// onError: ...)` (Review finding: previously never exercised by any
47	  /// test) — `null` (the default) keeps every other test's behavior
48	  /// unchanged (`const Stream.empty()`).
49	  StreamController<double>? amplitudeController;
50	
51	  @override
52	  Future<bool> hasPermission() async => permissionGranted;
53	
54	  @override
55	  Future<void> start() async => startCalls++;
56	
57	  @override
58	  Future<MicRecording?> stop() async => nextStopResult;
59	
60	  @override
61	  Future<void> cancel() async => cancelCalls++;
62	
63	  @override
64	  Stream<double> get amplitudeStream =>
65	      amplitudeController?.stream ?? const Stream.empty();
66	}
