75	/// `pickFromGallery` stays a trivial "never expected to be called" fake —
76	/// this file's own tests only ever drive the Foto tab's Câmera button
77	/// (spec-3-4's cross-tab tests), never Galeria. `pickFromCamera` is
78	/// configurable — spec-3-4's Foto→Áudio/chained tests need an in-flight
79	/// pick to switch away from (same `cameraGate` convention
80	/// `insertion_modal_photo_test.dart`'s own fake already uses).
81	class _FakePhotoPicker implements PhotoPicker {
82	  PickedPhoto? nextCameraResult;
83	  int cameraCalls = 0;
84	
85	  /// Lets a test hold `pickFromCamera()` unresolved, to simulate leaving
86	  /// the Foto tab (via a tab switch) while the native picker dialog is
87	  /// still open. `null` (the default) resolves immediately.
88	  Completer<void>? cameraGate;
89	
90	  @override
91	  Future<PickedPhoto?> pickFromCamera() async {
92	    cameraCalls++;
93	    final activeGate = cameraGate;
94	    if (activeGate != null) {
95	      await activeGate.future;
96	    }
97	    return nextCameraResult;
98	  }
99	
100	  @override
101	  Future<PickedPhoto?> pickFromGallery() async =>
102	      throw UnimplementedError('not expected to be called');
103	}
