143	Future<void> _openModal(
144	  WidgetTester tester, {
145	  required TextEntryCubit cubit,
146	  required AudioEntryCubit audioCubit,
147	  required PhotoEntryCubit photoCubit,
148	}) async {
149	  await tester.pumpWidget(
150	    MaterialApp(
151	      home: Scaffold(
152	        body: Builder(
153	          builder: (context) => ElevatedButton(
154	            onPressed: () => InsertionModal.show(
155	              context,
156	              cubit: cubit,
157	              audioCubit: audioCubit,
158	              photoCubit: photoCubit,
159	            ),
160	            child: const Text('open'),
161	          ),
162	        ),
163	      ),
164	    ),
165	  );
166	  await tester.tap(find.text('open'));
167	}
