169	/// Drives the real `InsertionModal` + real `AudioEntryCubit` through
170	/// spec-3-2's own I/O & Edge-Case Matrix — only the two native-package
171	/// ports are faked (see the classes above). `PhotoEntryCubit` is a fresh
172	/// instance, left unconfigured by every test except spec-3-4's own
173	/// cross-tab tests below, which do switch to the Foto tab and configure
174	/// `_FakePhotoPicker.nextCameraResult`/`cameraGate` to drive an in-flight
175	/// Câmera pick; `pickFromGallery()` stays untouched throughout — no test
176	/// in this file, including spec-3-4's, ever taps Galeria.
177	void main() {
178	  late _FakeMicRecorder fakeMicRecorder;
179	  late _FakeAudioTranscriber fakeAudioTranscriber;
180	  late _FakePhotoPicker fakePhotoPicker;
181	  late _FakeEntriesRepository fakeRepository;
182	  late TextEntryCubit textCubit;
183	  late AudioEntryCubit audioCubit;
184	  late PhotoEntryCubit photoCubit;
185	
186	  setUp(() {
187	    fakeMicRecorder = _FakeMicRecorder();
188	    fakeAudioTranscriber = _FakeAudioTranscriber();
189	    fakePhotoPicker = _FakePhotoPicker();
190	    fakeRepository = _FakeEntriesRepository();
191	    textCubit = TextEntryCubit(fakeRepository);
192	    audioCubit = AudioEntryCubit(
193	      fakeMicRecorder,
194	      fakeAudioTranscriber,
195	      fakeRepository,
196	    );
197	    photoCubit = PhotoEntryCubit(
198	      fakePhotoPicker,
199	      _FakeMediaRepository(),
200	      fakeRepository,
201	    );
202	  });
203	
204	  // Every test below opens the modal; the ones that never pop it (e.g. a
205	  // retry that leaves the sheet open) would otherwise leave
206	  // `AudioEntryCubit`'s own internal `Timer.periodic` (the elapsed-time
207	  // ticker) still pending once the test ends — `InsertionModal.show`
208	  // only closes both cubits once the sheet itself closes, which not
209	  // every scenario below reaches. `close()` is safe to call twice (it's
210	  // also called by `InsertionModal.show`'s own `finally` whenever a test
211	  // *does* pop the sheet), same convention
212	  // `text_entry_cubit_test.dart`'s own "emit after close" test relies on.
213	  tearDown(() async {
214	    // Every test below opens the modal; the ones that pop it (Salvar
215	    // success) already have both cubits closed by `InsertionModal.show`'s
216	    // own `finally` by the time this runs — guarding with `isClosed`
217	    // avoids calling `close()` a second time on an already-closed cubit,
218	    // which (confirmed while drafting this suite) hangs indefinitely
219	    // rather than being the harmless no-op `text_entry_cubit_test.dart`'s
220	    // own "emit after close" test relies on for a *bare* cubit (no
221	    // `BlocProvider`/widget tree attached there, unlike here).
222	    if (!textCubit.isClosed) {
223	      await textCubit.close();
224	    }
225	    if (!audioCubit.isClosed) {
226	      await audioCubit.close();
227	    }
228	    if (!photoCubit.isClosed) {
229	      await photoCubit.close();
230	    }
231	  });
232	
233	  testWidgets(
234	    'Happy path: switching to Áudio starts recording immediately with a '
235	    'running timer; stopping transcribes; Salvar fires source: audio + '
236	    'mediaDurationSeconds and closes the modal',
237	    (tester) async {
238	      fakeRepository.nextResult = () => right(_savedEntry);
239	      fakeMicRecorder.nextStopResult = const MicRecording(
240	        path: '/tmp/a.wav',
241	        durationSeconds: 7,
242	      );
243	      fakeAudioTranscriber.nextTranscription = 'Hoje foi um bom dia.';
244	      await _openModal(
245	        tester,
246	        cubit: textCubit,
247	        audioCubit: audioCubit,
248	        photoCubit: photoCubit,
249	      );
250	      await tester.pumpAndSettle();
251	
252	      await tester.tap(find.text('Áudio'));
253	      // A single `pump()`, never `pumpAndSettle()`, from here until the
254	      // recording stops below — `AudioEntryCubit`'s own 1-second
255	      // `Timer.periodic` (the elapsed-time ticker) never produces a
256	      // settled tree on its own; `pumpAndSettle()` would spin forever
257	      // waiting for a quiescent point that an active recording never
258	      // reaches.
259	      await tester.pump();
260	
261	      expect(fakeMicRecorder.startCalls, 1);
262	      expect(find.text('00:00'), findsOneWidget);
263	
264	      await tester.tap(find.byIcon(Icons.stop));
265	      await tester.pumpAndSettle();
266	
267	      expect(find.text('Hoje foi um bom dia.'), findsOneWidget);
268	      expect(find.byType(TextField), findsOneWidget);
269	
270	      await tester.tap(find.widgetWithText(ElevatedButton, 'Salvar'));
271	      await tester.pumpAndSettle();
272	
273	      expect(fakeRepository.createCallCount, 1);
274	      expect(fakeRepository.lastSource, EntrySource.audio);
275	      expect(fakeRepository.lastMediaDurationSeconds, 7);
276	      expect(find.byType(TextField), findsNothing);
277	    },
278	  );
279	
280	  testWidgets(
281	    'An amplitudeStream error while recording never escapes uncaught — '
282	    'the waveform just stays frozen on its last sample (Review finding: '
283	    'the real MicRecorder.amplitudeStream can surface a native-side '
284	    'error, which _Waveform guards with onError)',
285	    (tester) async {
286	      final amplitudeController = StreamController<double>();
287	      fakeMicRecorder.amplitudeController = amplitudeController;
288	      await _openModal(
289	        tester,
290	        cubit: textCubit,
291	        audioCubit: audioCubit,
292	        photoCubit: photoCubit,
293	      );
294	      await tester.pumpAndSettle();
295	
296	      await tester.tap(find.text('Áudio'));
297	      // Never `pumpAndSettle()` here — see the happy path test's own
298	      // comment on `AudioEntryCubit`'s 1-second elapsed-time ticker.
299	      await tester.pump();
300	      amplitudeController.add(0.6);
301	      await tester.pump();
302	
303	      amplitudeController.addError(Exception('native amplitude failure'));
304	      // If `onError` were ever dropped, this `pump()` is where the
305	      // uncaught stream error would surface as a failed test.
306	      await tester.pump();
307	
308	      expect(find.text('00:00'), findsOneWidget);
309	
310	      // Ends mid-recording — same cleanup as the other mid-recording
311	      // tests above. The controller is deliberately never `close()`d:
312	      // doing so under `flutter_test`'s `FakeAsync` zone needs its own
313	      // `pump()` afterward to flush the pending `done` microtask, and
314	      // nothing in this test needs that cleanup to pass.
315	      await audioCubit.cancel();
316	      await tester.pump();
317	    },
318	  );
319	
320	  testWidgets('Mic permission denied: AudioError shown, no file to preserve; '
321	      '"Tentar novamente" re-requests permission', (tester) async {
322	    fakeMicRecorder.permissionGranted = false;
323	    await _openModal(
324	      tester,
325	      cubit: textCubit,
326	      audioCubit: audioCubit,
327	      photoCubit: photoCubit,
328	    );
329	    await tester.pumpAndSettle();
330	
331	    await tester.tap(find.text('Áudio'));
332	    // Never `pumpAndSettle()` here — see the happy path test's own
333	    // comment on `AudioEntryCubit`'s 1-second elapsed-time ticker.
334	    await tester.pump();
335	
336	    expect(find.text('Tentar novamente'), findsOneWidget);
337	    expect(fakeMicRecorder.startCalls, 0);
338	
339	    fakeMicRecorder.permissionGranted = true;
340	    await tester.tap(find.text('Tentar novamente'));
341	    // Never `pumpAndSettle()` once recording starts — see the happy
342	    // path test's own comment.
343	    await tester.pump();
344	
345	    expect(fakeMicRecorder.startCalls, 1);
346	    expect(find.text('00:00'), findsOneWidget);
347	
348	    // This test ends mid-recording — `AudioEntryCubit`'s internal
349	    // `Timer.periodic` must be canceled before the test body returns
350	    // (not left to `tearDown`, which the framework's own pending-timer
351	    // invariant check runs ahead of): same as a real tab switch away
352	    // from Áudio (`cancel()`'s own I/O matrix row).
353	    await audioCubit.cancel();
354	    await tester.pump();
355	  });
356	
357	  testWidgets('Transcription fails: AudioError shown, audio file preserved; '
358	      '"Tentar novamente" re-transcribes the same file (never re-records)', (
359	    tester,
360	  ) async {
361	    fakeMicRecorder.nextStopResult = const MicRecording(
362	      path: '/tmp/a.wav',
363	      durationSeconds: 7,
364	    );
365	    fakeAudioTranscriber.nextTranscription = null;
366	    await _openModal(
367	      tester,
368	      cubit: textCubit,
369	      audioCubit: audioCubit,
370	      photoCubit: photoCubit,
371	    );
372	    await tester.pumpAndSettle();
373	
374	    await tester.tap(find.text('Áudio'));
375	    // Never `pumpAndSettle()` here — see the happy path test's own
376	    // comment on `AudioEntryCubit`'s 1-second elapsed-time ticker.
377	    await tester.pump();
378	    await tester.tap(find.byIcon(Icons.stop));
379	    await tester.pumpAndSettle();
380	
381	    expect(find.text('Tentar novamente'), findsOneWidget);
382	    expect(fakeMicRecorder.startCalls, 1);
383	
384	    fakeAudioTranscriber.nextTranscription = 'Funcionou na segunda vez.';
385	    await tester.tap(find.text('Tentar novamente'));
386	    await tester.pumpAndSettle();
387	
388	    expect(find.text('Funcionou na segunda vez.'), findsOneWidget);
389	    // Still only the original recording — retry re-transcribed, it
390	    // never started a second recording session.
391	    expect(fakeMicRecorder.startCalls, 1);
392	  });
393	
394	  testWidgets(
395	    'Save fails (incl. offline): inline Failure.message shown, Salvar '
396	    're-enabled, text/audio preserved, no auto-retry',
397	    (tester) async {
398	      fakeRepository.nextResult = () =>
399	          left(const Failure.networkOffline(message: 'Sem conexão'));
400	      fakeMicRecorder.nextStopResult = const MicRecording(
401	        path: '/tmp/a.wav',
402	        durationSeconds: 7,
403	      );
404	      fakeAudioTranscriber.nextTranscription = 'Hoje foi um bom dia.';
405	      await _openModal(
406	        tester,
407	        cubit: textCubit,
408	        audioCubit: audioCubit,
409	        photoCubit: photoCubit,
410	      );
411	      await tester.pumpAndSettle();
412	
413	      await tester.tap(find.text('Áudio'));
414	      // Never `pumpAndSettle()` here — see the happy path test's own
