290	  void _onTextEntryStateChange(BuildContext context, TextEntryState state) {
291	    // Review finding: a tab switch (re-emitted as `TextEntryIdle`,
292	    // same as every keystroke) previously went unannounced —
293	    // detected here by comparing against the last tab seen, so a
294	    // plain keystroke (same `activeTab`) never re-triggers it.
295	    if (state.activeTab != _lastAnnouncedTab) {
296	      final previousTab = _lastAnnouncedTab;
297	      _lastAnnouncedTab = state.activeTab;
298	      _announce('Aba ${_tabLabels[state.activeTab]} selecionada');
299	      // spec-3-2's Code Map: tab-switch detection also drives
300	      // `AudioEntryCubit.startRecording()`/`.cancel()` — entering Áudio
301	      // starts recording immediately (Acceptance Criteria), leaving it
302	      // stops/releases the recorder (I/O matrix: "Leave tab
303	      // mid-recording"), never the full Story 3.4 cancel choreography.
304	      final audioCubit = context.read<AudioEntryCubit>();
305	      if (state.activeTab == CaptureTab.audio) {
306	        unawaited(audioCubit.startRecording());
307	      } else if (previousTab == CaptureTab.audio) {
308	        unawaited(audioCubit.cancel());
309	      }
310	      // spec-3-3's Code Map: leaving Foto mid-pick/mid-OCR discards the
311	      // in-flight picker/OCR call (I/O matrix: "Leave tab mid-pick/OCR")
312	      // — unlike Áudio, entering Foto never starts anything on its own
313	      // (picking only ever starts from an explicit Câmera/Galeria tap).
314	      if (previousTab == CaptureTab.foto) {
315	        unawaited(context.read<PhotoEntryCubit>().cancel());
316	      }
317	    }
318	    switch (state) {
319	      case TextEntrySaved():
320	        // I/O matrix: "success closes the modal". Review finding:
321	        // wait for the announcement to actually be sent before
322	        // popping — previously fired-and-forgot in the same tick,
323	        // risking the announcement being cut off by the dismiss
324	        // transition.
325	        unawaited(
326	          _announce('Registro salvo').then((_) {
327	            if (context.mounted) {
328	              Navigator.of(context).pop();
329	            }
330	          }),
331	        );
332	      case TextEntrySaving():
333	        _announce('Salvando registro');
334	      case TextEntryError():
335	        _announce(state.message);
336	      case TextEntryIdle():
337	        break;
338	    }
339	  }
