201	    if (photo == null) {
202	      // I/O matrix: "User cancels picker" -> stays on PhotoIdle's capture
203	      // buttons. If the re-pick was attempted from a `payloadTooLarge`
204	      // error, drop that stale error too rather than leaving it on
205	      // screen with nothing that produced it anymore.
206	      if (current is PhotoError) {
207	        emit(const PhotoIdle());
208	      }
209	      return;
210	    }
211	    emit(PhotoProcessing(path: photo.path, mimeType: photo.mimeType));
212	    await _recognize(photo.path, photo.mimeType, generation);
213	  }
214	
215	  Future<void> _recognize(String path, String mimeType, int generation) async {
216	    Uint8List bytes;
217	    try {
218	      bytes = await File(path).readAsBytes();
219	    } catch (_) {
220	      if (isClosed || generation != _generation) {
221	        return;
222	      }
223	      emit(
224	        PhotoError(
225	          path: path,
226	          mimeType: mimeType,
227	          message: 'Não foi possível ler a foto selecionada.',
228	          kind: PhotoErrorKind.generic,
229	        ),
230	      );
231	      return;
232	    }
233	    final result = await _mediaRepository.recognizeText(
234	      imageBytes: bytes,
235	      mimeType: mimeType,
236	    );
237	    // Guards a tab switch away mid-OCR (`cancel()`, below) that already
238	    // reset the state by the time this resolves — without this, a stale
239	    // OCR result would still land and resurrect a flow the user left.
240	    if (isClosed || generation != _generation) {
241	      return;
242	    }
243	    result.match(
244	      (failure) => emit(
245	        PhotoError(
246	          path: path,
247	          mimeType: mimeType,
248	          message: failure.message,
249	          kind: switch (failure) {
250	            OcrNoText() => PhotoErrorKind.ocrNoText,
251	            PayloadTooLarge() => PhotoErrorKind.payloadTooLarge,
252	            _ => PhotoErrorKind.generic,
253	          },
254	        ),
255	      ),
256	      (ocr) => emit(
257	        PhotoRecognized(
258	          path: path,
259	          mimeType: mimeType,
260	          text: ocr.text,
261	          saving: false,
262	        ),
263	      ),
264	    );
265	  }
266	
267	  /// "Tentar novamente" — re-OCRs the same image for an [OcrNoText]
268	  /// error or a generic OCR-call failure ([PhotoError.text] `null`). A
269	  /// no-op for [PhotoErrorKind.payloadTooLarge] (I/O matrix: no retry
270	  /// offered) and for a generic *save* failure (non-null [PhotoError.
271	  /// text]) — that case's own retry is tapping Salvar again, handled by
272	  /// [save] directly, mirroring `AudioEntryCubit.retry()`.
273	  Future<void> retry() async {
274	    final current = state;
275	    if (current is! PhotoError ||
276	        current.text != null ||
277	        current.kind == PhotoErrorKind.payloadTooLarge) {
278	      return;
279	    }
280	    final generation = ++_generation;
281	    emit(PhotoProcessing(path: current.path, mimeType: current.mimeType));
282	    await _recognize(current.path, current.mimeType, generation);
283	  }
284	
285	  /// "Salvar só a foto" — only valid from an [OcrNoText] error; saves the
286	  /// fixed, non-empty placeholder content (the contract's
287	  /// `content.minLength: 1` forbids an empty save).
288	  Future<void> saveWithoutText() async {
289	    final current = state;
290	    if (current is! PhotoError || current.kind != PhotoErrorKind.ocrNoText) {
291	      return;
292	    }
293	    await _save(
294	      path: current.path,
295	      mimeType: current.mimeType,
296	      text: _noTextPlaceholder,
297	    );
298	  }
299	
300	  /// Mirrors the Texto/Áudio fields' own `updateText` — keeps the
301	  /// recognized text editable before Salvar, and keeps a save-failure
302	  /// retry's text editable too (same as `AudioEntryCubit.updateText`'s
303	  /// own `AudioError` branch).
304	  void updateText(String text) {
305	    final current = state;
306	    if (current is PhotoRecognized && !current.saving) {
307	      emit(current.copyWith(text: text));
308	    } else if (current is PhotoError &&
309	        current.kind == PhotoErrorKind.generic &&
310	        current.text != null) {
311	      emit(
312	        PhotoError(
313	          path: current.path,
314	          mimeType: current.mimeType,
315	          message: current.message,
316	          kind: current.kind,
317	          text: text,
318	        ),
319	      );
320	    }
321	  }
322	
323	  /// I/O matrix's "Happy path"/"Save fails" rows: fires `POST /entries`
324	  /// with `source: photo` for the current (possibly edited) recognized
325	  /// text. Also callable from a save-failure [PhotoError] (non-null
326	  /// [PhotoError.text]), mirroring `AudioEntryCubit.save()`'s own
327	  /// re-save-on-retry behavior.
328	  Future<void> save() async {
329	    final current = state;
330	    final String path;
331	    final String mimeType;
332	    final String text;
333	    if (current is PhotoRecognized && !current.saving) {
334	      path = current.path;
335	      mimeType = current.mimeType;
336	      text = current.text.trim();
337	    } else if (current is PhotoError &&
338	        current.kind == PhotoErrorKind.generic &&
339	        current.text != null) {
340	      path = current.path;
341	      mimeType = current.mimeType;
342	      text = current.text!.trim();
343	    } else {
344	      return;
345	    }
346	    if (text.isEmpty) {
347	      return;
348	    }
349	    await _save(path: path, mimeType: mimeType, text: text);
350	  }
351	
352	  Future<void> _save({
353	    required String path,
354	    required String mimeType,
355	    required String text,
356	  }) async {
357	    emit(
358	      PhotoRecognized(path: path, mimeType: mimeType, text: text, saving: true),
359	    );
360	    final result = await _entriesRepository.create(
361	      content: text,
362	      source: EntrySource.photo,
363	    );
364	    // Mirrors `AudioEntryCubit.save()`'s own `isClosed` guard — this
365	    // cubit's `close()` can race the awaited call above (e.g. the
366	    // modal's barrier is dismissed mid-save).
367	    if (isClosed) {
368	      return;
369	    }
370	    result.match(
371	      (failure) => emit(
372	        PhotoError(
373	          path: path,
374	          mimeType: mimeType,
375	          message: failure.message,
376	          kind: PhotoErrorKind.generic,
377	          text: text,
378	        ),
379	      ),
380	      (_) {
381	        // Review finding: the picked photo's temp file (written by
382	        // `image_picker` itself, not by this class, but still this
383	        // cubit's responsibility to clean up once it's done with it)
384	        // was never deleted after a successful save — fire-and-forget,
385	        // a deletion failure must never block the modal from closing.
386	        unawaited(_deletePickedFile(path));
387	        emit(const PhotoSaved());
388	      },
389	    );
390	  }
391	
392	  /// Called when the Foto tab loses focus mid-pick/mid-OCR
393	  /// (`InsertionModal`'s tab-switch listener) — I/O matrix's "Leave tab
394	  /// mid-pick/OCR" row: the in-flight picker/OCR call is discarded, no
395	  /// `create()` ever fires. A no-op for every other state when
396	  /// [discardPreserved] is `false` (the default) — in particular
397	  /// [PhotoRecognized]/[PhotoError], where the Never clause's trivial
398	  /// scope (resource safety only, not full Story 3.4 cancel-safety)
399	  /// means a tab switch must preserve the result rather than discard it
400	  /// — mirrors `AudioEntryCubit.cancel()`'s own `discardPreserved`
401	  /// convention exactly.
402	  ///
403	  /// [discardPreserved] — `InsertionModal.show()`'s `finally` also calls
404	  /// this (before `close()`) when the *whole modal* is dismissed (✕/
405	  /// swipe-down/barrier tap), not just the tab. In that case there's no
406	  /// "switch back to the tab later" to preserve for — the cubit is about
407	  /// to be closed — so a preserved [PhotoRecognized]/[PhotoError]'s
408	  /// picked-photo temp file would otherwise never be cleaned up and leak
409	  /// on disk forever (Review finding — the comment this replaced
410	  /// incorrectly claimed Foto "never creates a temp file of its own";
411	  /// `image_picker` does, every pick). Pass `true` only from that call
412	  /// site.
413	  Future<void> cancel({bool discardPreserved = false}) async {
414	    // Bumped unconditionally — including when the state below doesn't
415	    // match — so an in-flight `_pick`/`_recognize`/`retry` continuation
416	    // still sees the mismatch and aborts itself even while still awaiting
417	    // (Review-finding rationale mirrored from `AudioEntryCubit.cancel()`).
418	    _generation++;
419	    // Review finding: without this, leaving the Foto tab while the
420	    // native picker call itself (not yet `PhotoProcessing`) was still in
421	    // flight left `_picking` stuck `true` forever — the `_generation`
422	    // bump above already makes that stale continuation a no-op, so
423	    // resetting this eagerly is always safe.
424	    _picking = false;
425	    final current = state;
426	    if (current is PhotoProcessing) {
427	      unawaited(_deletePickedFile(current.path));
428	      emit(const PhotoIdle());
429	    } else if (discardPreserved) {
430	      final path = switch (current) {
431	        PhotoRecognized(path: final p) => p,
432	        PhotoError(path: final p) => p,
433	        _ => null,
434	      };
435	      if (path != null) {
436	        unawaited(_deletePickedFile(path));
437	      }
438	    }
439	  }
440	
441	  /// Best-effort cleanup for a picked-photo temp file this cubit is done
442	  /// with (saved successfully, abandoned for good by [cancel], or
443	  /// replaced by a fresh pick in [_pick]) — deletion failures are
444	  /// swallowed since nothing in the UI depends on this succeeding,
445	  /// mirroring `AudioEntryCubit._deleteRecordingFile()`.
446	  Future<void> _deletePickedFile(String path) async {
447	    try {
448	      await File(path).delete();
449	    } catch (_) {
450	      // Best-effort — a missing/already-deleted file, or a transient
451	      // disk error, is never worth surfacing to the user.
452	    }
453	  }
454	}
